def transform(grid):
    # For each row, recolor background cells after its rightmost foreground cell.
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        occupied = [c for c, value in enumerate(row) if value != background]
        if occupied:
            for c in range(occupied[-1] + 1, len(row)):
                if row[c] == background:
                    out[r][c] = 1
    return out

